import{_ as t,o as d,c as e,Q as o}from"./chunks/framework.48927342.js";const u=JSON.parse('{"title":"Verbs and Basic Tenses","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/grammar/04-verbs-tenses.md","filePath":"en/more/maltese/grammar/04-verbs-tenses.md"}'),c={name:"en/more/maltese/grammar/04-verbs-tenses.md"},a=o('<h1 id="verbs-and-basic-tenses" tabindex="-1">Verbs and Basic Tenses <a class="header-anchor" href="#verbs-and-basic-tenses" aria-label="Permalink to &quot;Verbs and Basic Tenses&quot;">​</a></h1><p>This chapter is organized as “rules → tense-specific conjugation → comparison.” Maltese commonly uses the imperfect to express present, habitual, or ongoing actions; the perfect expresses completed actions; and the future is often formed with <code>se + imperfect</code>. These forms do not map one-to-one onto English tenses; context and time expressions also matter.</p><h2 id="_1-three-common-constructions" tabindex="-1">1. Three Common Constructions <a class="header-anchor" href="#_1-three-common-constructions" aria-label="Permalink to &quot;1. Three Common Constructions&quot;">​</a></h2><table><thead><tr><th>Learning label</th><th>Maltese form</th><th>Common use</th><th>Example</th></tr></thead><tbody><tr><td>Present/habitual: imperfect</td><td>person form + verb stem</td><td>Current state, habitual action, or an action not yet complete</td><td><code>Jien nikteb.</code>: I write / I am writing.</td></tr><tr><td>Past: perfect</td><td>person form of the perfect</td><td>Completed action or event</td><td><code>Jien ktibt.</code>: I wrote.</td></tr><tr><td>Future</td><td><code>se + imperfect</code></td><td>Planned, predicted, or future action</td><td><code>Jien se nikteb.</code>: I will write.</td></tr></tbody></table><p>The imperfect and perfect are form/aspect categories, not exact equivalents of English present and past. Context and time expressions help establish the time. Person forms are explained in <a href="./03-person-conjugation.html">Personal Pronouns and Verb Conjugation</a>.</p><h2 id="_2-imperfect-and-perfect" tabindex="-1">2. Imperfect and Perfect <a class="header-anchor" href="#_2-imperfect-and-perfect" aria-label="Permalink to &quot;2. Imperfect and Perfect&quot;">​</a></h2><p>The Maltese verb system commonly uses the terms “imperfect” and “perfect” for forms/aspects. As a beginner approximation, the imperfect can express present, habitual, or unfinished actions, while the perfect can express completed actions (often corresponding to the past). This is not a one-to-one mapping with English tenses. Maltese has no infinitive that corresponds exactly to English <code>to eat</code>.</p><h2 id="_3-present-or-habitual-actions-imperfect" tabindex="-1">3. Present or Habitual Actions: Imperfect <a class="header-anchor" href="#_3-present-or-habitual-actions-imperfect" aria-label="Permalink to &quot;3. Present or Habitual Actions: Imperfect&quot;">​</a></h2><p>Verb forms change by person and may also change their endings. Using <code>kiteb</code> (write) as an example:</p><table><thead><tr><th>Person</th><th>Malti</th><th>Meaning</th></tr></thead><tbody><tr><td>I</td><td>nikteb</td><td>I write / I am writing</td></tr><tr><td>you (singular)</td><td>tikteb</td><td>you write / you are writing</td></tr><tr><td>he</td><td>jikteb</td><td>he writes / he is writing</td></tr><tr><td>she</td><td>tikteb</td><td>she writes / she is writing</td></tr><tr><td>we</td><td>niktbu</td><td>we write / we are writing</td></tr><tr><td>you (plural)</td><td>tiktbu</td><td>you write / you are writing</td></tr><tr><td>they</td><td>jiktbu</td><td>they write / they are writing</td></tr></tbody></table><p>Examples:</p><ul><li><code>Jien nikteb ittra.</code>: I write a letter.</li><li><code>Hi taqra ktieb.</code>: She reads a book.</li><li><code>Aħna naħdmu hawn.</code>: We work here.</li></ul><p>Context or a time expression usually indicates whether an action is happening right now; the imperfect does not only mean “currently in progress.”</p><h3 id="present-tense-conjugations-and-examples" tabindex="-1">Present-Tense Conjugations and Examples <a class="header-anchor" href="#present-tense-conjugations-and-examples" aria-label="Permalink to &quot;Present-Tense Conjugations and Examples&quot;">​</a></h3><p>The glosses are in English and Maltese citation forms. The seven person columns are <code>jien</code>, <code>inti</code>, <code>hu</code>, <code>hi</code>, <code>aħna</code>, <code>intom</code>, and <code>huma</code>. Example sentences use first-person singular.</p><table><thead><tr><th>English</th><th>Malti citation form</th><th>jien</th><th>inti</th><th>hu</th><th>hi</th><th>aħna</th><th>intom</th><th>huma</th></tr></thead><tbody><tr><td>write</td><td>kiteb</td><td><code>nikteb</code></td><td><code>tikteb</code></td><td><code>jikteb</code></td><td><code>tikteb</code></td><td><code>niktbu</code></td><td><code>tiktbu</code></td><td><code>jiktbu</code></td></tr><tr><td>read</td><td>qara</td><td><code>naqra</code></td><td><code>taqra</code></td><td><code>jaqra</code></td><td><code>taqra</code></td><td><code>naqraw</code></td><td><code>taqraw</code></td><td><code>jaqraw</code></td></tr><tr><td>eat</td><td>kiel</td><td><code>niekol</code></td><td><code>tiekol</code></td><td><code>jiekol</code></td><td><code>tiekol</code></td><td><code>nieklu</code></td><td><code>tieklu</code></td><td><code>jieklu</code></td></tr><tr><td>drink</td><td>xorob</td><td><code>nixrob</code></td><td><code>tixrob</code></td><td><code>jixrob</code></td><td><code>tixrob</code></td><td><code>nixorbu</code></td><td><code>tixorbu</code></td><td><code>jixorbu</code></td></tr><tr><td>work</td><td>ħadem</td><td><code>naħdem</code></td><td><code>taħdem</code></td><td><code>jaħdem</code></td><td><code>taħdem</code></td><td><code>naħdmu</code></td><td><code>taħdmu</code></td><td><code>jaħdmu</code></td></tr><tr><td>speak</td><td>tkellem</td><td><code>nitkellem</code></td><td><code>titkellem</code></td><td><code>jitkellem</code></td><td><code>titkellem</code></td><td><code>nitkellmu</code></td><td><code>titkellmu</code></td><td><code>jitkellmu</code></td></tr><tr><td>go</td><td>mar</td><td><code>mmur</code></td><td><code>tmur</code></td><td><code>jmur</code></td><td><code>tmur</code></td><td><code>mmorru</code></td><td><code>tmorru</code></td><td><code>jmorru</code></td></tr><tr><td>come</td><td>ġie</td><td><code>niġi</code></td><td><code>tiġi</code></td><td><code>jiġi</code></td><td><code>tiġi</code></td><td><code>niġu</code></td><td><code>tiġu</code></td><td><code>jiġu</code></td></tr><tr><td>find</td><td>sab</td><td><code>nsib</code></td><td><code>ssib</code></td><td><code>jsib</code></td><td><code>ssib</code></td><td><code>nsibu</code></td><td><code>ssibu</code></td><td><code>jsibu</code></td></tr><tr><td>wait</td><td>stenna</td><td><code>nistenna</code></td><td><code>tistenna</code></td><td><code>jistenna</code></td><td><code>tistenna</code></td><td><code>nistennew</code></td><td><code>tistennew</code></td><td><code>jistennew</code></td></tr><tr><td>make/do</td><td>għamel</td><td><code>nagħmel</code></td><td><code>tagħmel</code></td><td><code>jagħmel</code></td><td><code>tagħmel</code></td><td><code>nagħmlu</code></td><td><code>tagħmlu</code></td><td><code>jagħmlu</code></td></tr><tr><td>help</td><td>għen</td><td><code>ngħin</code></td><td><code>tgħin</code></td><td><code>jgħin</code></td><td><code>tgħin</code></td><td><code>ngħinu</code></td><td><code>tgħinu</code></td><td><code>jgħinu</code></td></tr><tr><td>live</td><td>għex</td><td><code>ngħix</code></td><td><code>tgħix</code></td><td><code>jgħix</code></td><td><code>tgħix</code></td><td><code>ngħixu</code></td><td><code>tgħixu</code></td><td><code>jgħixu</code></td></tr><tr><td>close</td><td>għalaq</td><td><code>nagħlaq</code></td><td><code>tagħlaq</code></td><td><code>jagħlaq</code></td><td><code>tagħlaq</code></td><td><code>nagħlqu</code></td><td><code>tagħlqu</code></td><td><code>jagħlqu</code></td></tr><tr><td>choose</td><td>għażel</td><td><code>nagħżel</code></td><td><code>tagħżel</code></td><td><code>jagħżel</code></td><td><code>tagħżel</code></td><td><code>nagħżlu</code></td><td><code>tagħżlu</code></td><td><code>jagħżlu</code></td></tr><tr><td>send</td><td>bagħat</td><td><code>nibgħat</code></td><td><code>tibgħat</code></td><td><code>jibgħat</code></td><td><code>tibgħat</code></td><td><code>nibagħtu</code></td><td><code>tibagħtu</code></td><td><code>jibagħtu</code></td></tr><tr><td>stay</td><td>qagħad</td><td><code>noqgħod</code></td><td><code>toqgħod</code></td><td><code>joqgħod</code></td><td><code>toqgħod</code></td><td><code>noqogħdu</code></td><td><code>toqogħdu</code></td><td><code>joqogħdu</code></td></tr><tr><td>sell</td><td>biegħ</td><td><code>nbigħ</code></td><td><code>tbigħ</code></td><td><code>jbigħ</code></td><td><code>tbigħ</code></td><td><code>nbigħu</code></td><td><code>tbigħu</code></td><td><code>jbigħu</code></td></tr><tr><td>switch on</td><td>xegħel</td><td><code>nixgħel</code></td><td><code>tixgħel</code></td><td><code>jixgħel</code></td><td><code>tixgħel</code></td><td><code>nixegħlu</code></td><td><code>tixegħlu</code></td><td><code>jixegħlu</code></td></tr><tr><td>be surprised</td><td>stagħġeb</td><td><code>nistagħġeb</code></td><td><code>tistagħġeb</code></td><td><code>jistagħġeb</code></td><td><code>tistagħġeb</code></td><td><code>nistagħġbu</code></td><td><code>tistagħġbu</code></td><td><code>jistagħġbu</code></td></tr></tbody></table><table><thead><tr><th>Verb</th><th>English example</th><th>Malti example</th></tr></thead><tbody><tr><td>kiteb</td><td>I write a letter.</td><td>Jien nikteb ittra.</td></tr><tr><td>qara</td><td>I read a book.</td><td>Jien naqra ktieb.</td></tr><tr><td>kiel</td><td>I eat bread.</td><td>Jien niekol il-ħobż.</td></tr><tr><td>xorob</td><td>I drink water.</td><td>Jien nixrob l-ilma.</td></tr><tr><td>ħadem</td><td>I work at home.</td><td>Jien naħdem id-dar.</td></tr><tr><td>tkellem</td><td>I speak Maltese.</td><td>Jien nitkellem bil-Malti.</td></tr><tr><td>mar</td><td>I go to school.</td><td>Jien immur l-iskola.</td></tr><tr><td>ġie</td><td>I come to Malta.</td><td>Jien niġi Malta.</td></tr><tr><td>sab</td><td>I find the key.</td><td>Jien insib iċ-ċavetta.</td></tr><tr><td>stenna</td><td>I wait for the bus.</td><td>Jien nistenna l-karozza tal-linja.</td></tr><tr><td>għamel</td><td>I make dinner.</td><td>Jien nagħmel l-ikla ta&#39; filgħaxija.</td></tr><tr><td>għen</td><td>I help a friend.</td><td>Jien ngħin lil ħabib.</td></tr><tr><td>għex</td><td>I live in Malta.</td><td>Jien ngħix f&#39;Malta.</td></tr><tr><td>għalaq</td><td>I close the door.</td><td>Jien nagħlaq il-bieb.</td></tr><tr><td>għażel</td><td>I choose a book.</td><td>Jien nagħżel ktieb.</td></tr><tr><td>bagħat</td><td>I send a message.</td><td>Jien nibgħat messaġġ.</td></tr><tr><td>qagħad</td><td>I stay at home.</td><td>Jien noqgħod id-dar.</td></tr><tr><td>biegħ</td><td>I sell books.</td><td>Jien nbigħ kotba.</td></tr><tr><td>xegħel</td><td>I switch on the light.</td><td>Jien nixgħel id-dawl.</td></tr><tr><td>stagħġeb</td><td>I am surprised.</td><td>Jien nistagħġeb.</td></tr></tbody></table><h2 id="_4-completed-actions-perfect" tabindex="-1">4. Completed Actions: Perfect <a class="header-anchor" href="#_4-completed-actions-perfect" aria-label="Permalink to &quot;4. Completed Actions: Perfect&quot;">​</a></h2><p>Using <code>kiteb</code> (write), the perfect commonly describes a completed past action:</p><table><thead><tr><th>Person</th><th>Malti</th><th>Meaning</th></tr></thead><tbody><tr><td>I</td><td>ktibt</td><td>I wrote</td></tr><tr><td>you (singular)</td><td>ktibt</td><td>you wrote</td></tr><tr><td>he</td><td>kiteb</td><td>he wrote</td></tr><tr><td>she</td><td>kitbet</td><td>she wrote</td></tr><tr><td>we</td><td>ktibna</td><td>we wrote</td></tr><tr><td>you (plural)</td><td>ktibtu</td><td>you wrote</td></tr><tr><td>they</td><td>kitbu</td><td>they wrote</td></tr></tbody></table><p>Examples:</p><ul><li><code>Ilbieraħ ktibt ittra.</code>: Yesterday I wrote a letter.</li><li><code>Hu kiel il-ħobż.</code>: He ate the bread.</li><li><code>Morna r-ristorant.</code>: We went to the restaurant.</li></ul><p>Perfect forms involve stem changes; do not mechanically apply one verb&#39;s forms to all verbs. See <a href="./03-person-conjugation.html">Personal Pronouns and Verb Conjugation</a> for more person forms.</p><h3 id="past-tense-conjugations-and-examples" tabindex="-1">Past-Tense Conjugations and Examples <a class="header-anchor" href="#past-tense-conjugations-and-examples" aria-label="Permalink to &quot;Past-Tense Conjugations and Examples&quot;">​</a></h3><p>The person columns are <code>jien</code>, <code>inti</code>, <code>hu</code>, <code>hi</code>, <code>aħna</code>, <code>intom</code>, and <code>huma</code>. Example sentences use first-person singular.</p><table><thead><tr><th>English</th><th>Malti citation form</th><th>jien</th><th>inti</th><th>hu</th><th>hi</th><th>aħna</th><th>intom</th><th>huma</th></tr></thead><tbody><tr><td>write</td><td>kiteb</td><td><code>ktibt</code></td><td><code>ktibt</code></td><td><code>kiteb</code></td><td><code>kitbet</code></td><td><code>ktibna</code></td><td><code>ktibtu</code></td><td><code>kitbu</code></td></tr><tr><td>read</td><td>qara</td><td><code>qrajt</code></td><td><code>qrajt</code></td><td><code>qara</code></td><td><code>qrat</code></td><td><code>qrajna</code></td><td><code>qrajtu</code></td><td><code>qraw</code></td></tr><tr><td>eat</td><td>kiel</td><td><code>kilt</code></td><td><code>kilt</code></td><td><code>kiel</code></td><td><code>kielet</code></td><td><code>kilna</code></td><td><code>kiltu</code></td><td><code>kielu</code></td></tr><tr><td>drink</td><td>xorob</td><td><code>xrobt</code></td><td><code>xrobt</code></td><td><code>xorob</code></td><td><code>xorbot</code></td><td><code>xrobna</code></td><td><code>xrobtu</code></td><td><code>xorbu</code></td></tr><tr><td>work</td><td>ħadem</td><td><code>ħdimt</code></td><td><code>ħdimt</code></td><td><code>ħadem</code></td><td><code>ħadmet</code></td><td><code>ħdimna</code></td><td><code>ħdimtu</code></td><td><code>ħadmu</code></td></tr><tr><td>speak</td><td>tkellem</td><td><code>tkellimt</code></td><td><code>tkellimt</code></td><td><code>tkellem</code></td><td><code>tkellmet</code></td><td><code>tkellimna</code></td><td><code>tkellimtu</code></td><td><code>tkellmu</code></td></tr><tr><td>go</td><td>mar</td><td><code>mort</code></td><td><code>mort</code></td><td><code>mar</code></td><td><code>marret</code></td><td><code>morna</code></td><td><code>mortu</code></td><td><code>marru</code></td></tr><tr><td>come</td><td>ġie</td><td><code>ġejt</code></td><td><code>ġejt</code></td><td><code>ġie</code></td><td><code>ġiet</code></td><td><code>ġejna</code></td><td><code>ġejtu</code></td><td><code>ġew</code></td></tr><tr><td>find</td><td>sab</td><td><code>sibt</code></td><td><code>sibt</code></td><td><code>sab</code></td><td><code>sabet</code></td><td><code>sibna</code></td><td><code>sibtu</code></td><td><code>sabu</code></td></tr><tr><td>wait</td><td>stenna</td><td><code>stennejt</code></td><td><code>stennejt</code></td><td><code>stenna</code></td><td><code>stenniet</code></td><td><code>stennejna</code></td><td><code>stennejtu</code></td><td><code>stennew</code></td></tr><tr><td>make/do</td><td>għamel</td><td><code>għamilt</code></td><td><code>għamilt</code></td><td><code>għamel</code></td><td><code>għamlet</code></td><td><code>għamilna</code></td><td><code>għamiltu</code></td><td><code>għamlu</code></td></tr><tr><td>help</td><td>għen</td><td><code>għent</code></td><td><code>għent</code></td><td><code>għen</code></td><td><code>għenet</code></td><td><code>għenna</code></td><td><code>għentu</code></td><td><code>għenu</code></td></tr><tr><td>live</td><td>għex</td><td><code>għext</code></td><td><code>għext</code></td><td><code>għex</code></td><td><code>għexet</code></td><td><code>għexna</code></td><td><code>għextu</code></td><td><code>għexu</code></td></tr><tr><td>close</td><td>għalaq</td><td><code>għalaqt</code></td><td><code>għalaqt</code></td><td><code>għalaq</code></td><td><code>għalqet</code></td><td><code>għalaqna</code></td><td><code>għalaqtu</code></td><td><code>għalqu</code></td></tr><tr><td>choose</td><td>għażel</td><td><code>għażilt</code></td><td><code>għażilt</code></td><td><code>għażel</code></td><td><code>għażlet</code></td><td><code>għażilna</code></td><td><code>għażiltu</code></td><td><code>għażlu</code></td></tr><tr><td>send</td><td>bagħat</td><td><code>bgħatt</code></td><td><code>bgħatt</code></td><td><code>bagħat</code></td><td><code>bagħtet</code></td><td><code>bgħatna</code></td><td><code>bgħattu</code></td><td><code>bagħtu</code></td></tr><tr><td>stay</td><td>qagħad</td><td><code>qgħadt</code></td><td><code>qgħadt</code></td><td><code>qagħad</code></td><td><code>qagħdet</code></td><td><code>qgħadna</code></td><td><code>qgħadtu</code></td><td><code>qagħdu</code></td></tr><tr><td>sell</td><td>biegħ</td><td><code>begħt</code></td><td><code>begħt</code></td><td><code>biegħ</code></td><td><code>biegħet</code></td><td><code>begħna</code></td><td><code>begħtu</code></td><td><code>biegħu</code></td></tr><tr><td>switch on</td><td>xegħel</td><td><code>xgħelt</code></td><td><code>xgħelt</code></td><td><code>xegħel</code></td><td><code>xegħlet</code></td><td><code>xgħelna</code></td><td><code>xgħeltu</code></td><td><code>xegħlu</code></td></tr><tr><td>be surprised</td><td>stagħġeb</td><td><code>stagħġibt</code></td><td><code>stagħġibt</code></td><td><code>stagħġeb</code></td><td><code>stagħġbet</code></td><td><code>stagħġibna</code></td><td><code>stagħġibtu</code></td><td><code>stagħġbu</code></td></tr></tbody></table><table><thead><tr><th>Verb</th><th>English example</th><th>Malti example</th></tr></thead><tbody><tr><td>kiteb</td><td>I wrote a letter.</td><td>Jien ktibt ittra.</td></tr><tr><td>qara</td><td>I read a book.</td><td>Jien qrajt ktieb.</td></tr><tr><td>kiel</td><td>I ate bread.</td><td>Jien kilt il-ħobż.</td></tr><tr><td>xorob</td><td>I drank water.</td><td>Jien xorbt l-ilma.</td></tr><tr><td>ħadem</td><td>I worked at home.</td><td>Jien ħdimt id-dar.</td></tr><tr><td>tkellem</td><td>I spoke Maltese.</td><td>Jien tkellimt bil-Malti.</td></tr><tr><td>mar</td><td>I went to school.</td><td>Jien mort l-iskola.</td></tr><tr><td>ġie</td><td>I came to Malta.</td><td>Jien ġejt Malta.</td></tr><tr><td>sab</td><td>I found the key.</td><td>Jien sibt iċ-ċavetta.</td></tr><tr><td>stenna</td><td>I waited for the bus.</td><td>Jien stennejt il-karozza tal-linja.</td></tr><tr><td>għamel</td><td>I made dinner.</td><td>Jien għamilt l-ikla ta&#39; filgħaxija.</td></tr><tr><td>għen</td><td>I helped a friend.</td><td>Jien għent lil ħabib.</td></tr><tr><td>għex</td><td>I lived in Malta.</td><td>Jien għext f&#39;Malta.</td></tr><tr><td>għalaq</td><td>I closed the door.</td><td>Jien għalaqt il-bieb.</td></tr><tr><td>għażel</td><td>I chose a book.</td><td>Jien għażilt ktieb.</td></tr><tr><td>bagħat</td><td>I sent a message.</td><td>Jien bgħatt messaġġ.</td></tr><tr><td>qagħad</td><td>I stayed at home.</td><td>Jien qgħadt id-dar.</td></tr><tr><td>biegħ</td><td>I sold books.</td><td>Jien begħt kotba.</td></tr><tr><td>xegħel</td><td>I switched on the light.</td><td>Jien xgħelt id-dawl.</td></tr><tr><td>stagħġeb</td><td>I was surprised.</td><td>Jien stagħġibt.</td></tr></tbody></table><h2 id="_5-future" tabindex="-1">5. Future <a class="header-anchor" href="#_5-future" aria-label="Permalink to &quot;5. Future&quot;">​</a></h2><p>A common construction places the future marker <code>se</code> (also <code>ser</code>) or <code>ħa</code> before the imperfect. Time words such as <code>għada</code> (tomorrow) can also indicate the future.</p><ul><li><code>Għada se mmur Malta.</code>: Tomorrow I will go to Malta.</li><li><code>Se nikteb l-ittra.</code>: I will write the letter.</li><li><code>Ħa nieklu issa.</code>: We are going to eat now.</li></ul><p>Usage of <code>se</code>, <code>ser</code>, and <code>ħa</code> varies with colloquial habit and context. Beginners can start with <code>se + imperfect</code>.</p><h3 id="future-tense-conjugations-and-examples" tabindex="-1">Future-Tense Conjugations and Examples <a class="header-anchor" href="#future-tense-conjugations-and-examples" aria-label="Permalink to &quot;Future-Tense Conjugations and Examples&quot;">​</a></h3><p>Each person uses <code>se + imperfect</code>. Person columns are <code>jien</code>, <code>inti</code>, <code>hu</code>, <code>hi</code>, <code>aħna</code>, <code>intom</code>, and <code>huma</code>.</p><table><thead><tr><th>English</th><th>Malti citation form</th><th>jien</th><th>inti</th><th>hu</th><th>hi</th><th>aħna</th><th>intom</th><th>huma</th></tr></thead><tbody><tr><td>write</td><td>kiteb</td><td><code>se nikteb</code></td><td><code>se tikteb</code></td><td><code>se jikteb</code></td><td><code>se tikteb</code></td><td><code>se niktbu</code></td><td><code>se tiktbu</code></td><td><code>se jiktbu</code></td></tr><tr><td>read</td><td>qara</td><td><code>se naqra</code></td><td><code>se taqra</code></td><td><code>se jaqra</code></td><td><code>se taqra</code></td><td><code>se naqraw</code></td><td><code>se taqraw</code></td><td><code>se jaqraw</code></td></tr><tr><td>eat</td><td>kiel</td><td><code>se niekol</code></td><td><code>se tiekol</code></td><td><code>se jiekol</code></td><td><code>se tiekol</code></td><td><code>se nieklu</code></td><td><code>se tieklu</code></td><td><code>se jieklu</code></td></tr><tr><td>drink</td><td>xorob</td><td><code>se nixrob</code></td><td><code>se tixrob</code></td><td><code>se jixrob</code></td><td><code>se tixrob</code></td><td><code>se nixorbu</code></td><td><code>se tixorbu</code></td><td><code>se jixorbu</code></td></tr><tr><td>work</td><td>ħadem</td><td><code>se naħdem</code></td><td><code>se taħdem</code></td><td><code>se jaħdem</code></td><td><code>se taħdem</code></td><td><code>se naħdmu</code></td><td><code>se taħdmu</code></td><td><code>se jaħdmu</code></td></tr><tr><td>speak</td><td>tkellem</td><td><code>se nitkellem</code></td><td><code>se titkellem</code></td><td><code>se jitkellem</code></td><td><code>se titkellem</code></td><td><code>se nitkellmu</code></td><td><code>se titkellmu</code></td><td><code>se jitkellmu</code></td></tr><tr><td>go</td><td>mar</td><td><code>se mmur</code></td><td><code>se tmur</code></td><td><code>se jmur</code></td><td><code>se tmur</code></td><td><code>se mmorru</code></td><td><code>se tmorru</code></td><td><code>se jmorru</code></td></tr><tr><td>come</td><td>ġie</td><td><code>se niġi</code></td><td><code>se tiġi</code></td><td><code>se jiġi</code></td><td><code>se tiġi</code></td><td><code>se niġu</code></td><td><code>se tiġu</code></td><td><code>se jiġu</code></td></tr><tr><td>find</td><td>sab</td><td><code>se nsib</code></td><td><code>se ssib</code></td><td><code>se jsib</code></td><td><code>se ssib</code></td><td><code>se nsibu</code></td><td><code>se ssibu</code></td><td><code>se jsibu</code></td></tr><tr><td>wait</td><td>stenna</td><td><code>se nistenna</code></td><td><code>se tistenna</code></td><td><code>se jistenna</code></td><td><code>se tistenna</code></td><td><code>se nistennew</code></td><td><code>se tistennew</code></td><td><code>se jistennew</code></td></tr><tr><td>make/do</td><td>għamel</td><td><code>se nagħmel</code></td><td><code>se tagħmel</code></td><td><code>se jagħmel</code></td><td><code>se tagħmel</code></td><td><code>se nagħmlu</code></td><td><code>se tagħmlu</code></td><td><code>se jagħmlu</code></td></tr><tr><td>help</td><td>għen</td><td><code>se ngħin</code></td><td><code>se tgħin</code></td><td><code>se jgħin</code></td><td><code>se tgħin</code></td><td><code>se ngħinu</code></td><td><code>se tgħinu</code></td><td><code>se jgħinu</code></td></tr><tr><td>live</td><td>għex</td><td><code>se ngħix</code></td><td><code>se tgħix</code></td><td><code>se jgħix</code></td><td><code>se tgħix</code></td><td><code>se ngħixu</code></td><td><code>se tgħixu</code></td><td><code>se jgħixu</code></td></tr><tr><td>close</td><td>għalaq</td><td><code>se nagħlaq</code></td><td><code>se tagħlaq</code></td><td><code>se jagħlaq</code></td><td><code>se tagħlaq</code></td><td><code>se nagħlqu</code></td><td><code>se tagħlqu</code></td><td><code>se jagħlqu</code></td></tr><tr><td>choose</td><td>għażel</td><td><code>se nagħżel</code></td><td><code>se tagħżel</code></td><td><code>se jagħżel</code></td><td><code>se tagħżel</code></td><td><code>se nagħżlu</code></td><td><code>se tagħżlu</code></td><td><code>se jagħżlu</code></td></tr><tr><td>send</td><td>bagħat</td><td><code>se nibgħat</code></td><td><code>se tibgħat</code></td><td><code>se jibgħat</code></td><td><code>se tibgħat</code></td><td><code>se nibagħtu</code></td><td><code>se tibagħtu</code></td><td><code>se jibagħtu</code></td></tr><tr><td>stay</td><td>qagħad</td><td><code>se noqgħod</code></td><td><code>se toqgħod</code></td><td><code>se joqgħod</code></td><td><code>se toqgħod</code></td><td><code>se noqogħdu</code></td><td><code>se toqogħdu</code></td><td><code>se joqogħdu</code></td></tr><tr><td>sell</td><td>biegħ</td><td><code>se nbigħ</code></td><td><code>se tbigħ</code></td><td><code>se jbigħ</code></td><td><code>se tbigħ</code></td><td><code>se nbigħu</code></td><td><code>se tbigħu</code></td><td><code>se jbigħu</code></td></tr><tr><td>switch on</td><td>xegħel</td><td><code>se nixgħel</code></td><td><code>se tixgħel</code></td><td><code>se jixgħel</code></td><td><code>se tixgħel</code></td><td><code>se nixegħlu</code></td><td><code>se tixegħlu</code></td><td><code>se jixegħlu</code></td></tr><tr><td>be surprised</td><td>stagħġeb</td><td><code>se nistagħġeb</code></td><td><code>se tistagħġeb</code></td><td><code>se jistagħġeb</code></td><td><code>se tistagħġeb</code></td><td><code>se nistagħġbu</code></td><td><code>se tistagħġbu</code></td><td><code>se jistagħġbu</code></td></tr></tbody></table><table><thead><tr><th>Verb</th><th>English example</th><th>Malti example</th></tr></thead><tbody><tr><td>kiteb</td><td>I will write a letter.</td><td>Jien se nikteb ittra.</td></tr><tr><td>qara</td><td>I will read a book.</td><td>Jien se naqra ktieb.</td></tr><tr><td>kiel</td><td>I will eat bread.</td><td>Jien se niekol il-ħobż.</td></tr><tr><td>xorob</td><td>I will drink water.</td><td>Jien se nixrob l-ilma.</td></tr><tr><td>ħadem</td><td>I will work at home.</td><td>Jien se naħdem id-dar.</td></tr><tr><td>tkellem</td><td>I will speak Maltese.</td><td>Jien se nitkellem bil-Malti.</td></tr><tr><td>mar</td><td>I will go to school.</td><td>Jien se mmur l-iskola.</td></tr><tr><td>ġie</td><td>I will come to Malta.</td><td>Jien se niġi Malta.</td></tr><tr><td>sab</td><td>I will find the key.</td><td>Jien se nsib iċ-ċavetta.</td></tr><tr><td>stenna</td><td>I will wait for the bus.</td><td>Jien se nistenna l-karozza tal-linja.</td></tr><tr><td>għamel</td><td>I will make dinner.</td><td>Jien se nagħmel l-ikla ta&#39; filgħaxija.</td></tr><tr><td>għen</td><td>I will help a friend.</td><td>Jien se ngħin lil ħabib.</td></tr><tr><td>għex</td><td>I will live in Malta.</td><td>Jien se ngħix f&#39;Malta.</td></tr><tr><td>għalaq</td><td>I will close the door.</td><td>Jien se nagħlaq il-bieb.</td></tr><tr><td>għażel</td><td>I will choose a book.</td><td>Jien se nagħżel ktieb.</td></tr><tr><td>bagħat</td><td>I will send a message.</td><td>Jien se nibgħat messaġġ.</td></tr><tr><td>qagħad</td><td>I will stay at home.</td><td>Jien se noqgħod id-dar.</td></tr><tr><td>biegħ</td><td>I will sell books.</td><td>Jien se nbigħ kotba.</td></tr><tr><td>xegħel</td><td>I will switch on the light.</td><td>Jien se nixgħel id-dawl.</td></tr><tr><td>stagħġeb</td><td>I will be surprised.</td><td>Jien se nistagħġeb.</td></tr></tbody></table><h2 id="_6-introductory-negation-and-questions" tabindex="-1">6. Introductory Negation and Questions <a class="header-anchor" href="#_6-introductory-negation-and-questions" aria-label="Permalink to &quot;6. Introductory Negation and Questions&quot;">​</a></h2><ul><li>A common negative frame is <code>ma ... x</code>: <code>Ma nafx.</code> (I don&#39;t know); <code>Ma nifhimx.</code> (I don&#39;t understand). Individual verbs may show form changes.</li><li>Yes/no questions can be formed through intonation or context: <code>Titkellem bl-Ingliż?</code> (Do you speak English?)</li><li>Question words often come first: <code>Fejn tgħix?</code> (Where do you live?)</li></ul><h2 id="_7-study-tips" tabindex="-1">7. Study Tips <a class="header-anchor" href="#_7-study-tips" aria-label="Permalink to &quot;7. Study Tips&quot;">​</a></h2><p>First learn the common imperfect forms of “write,” then practise <code>jiekol</code> (eat), <code>jaqra</code> (read), and <code>jaħdem</code> (work) in simple sentences. For each new verb, learn one first-person form and one he/she form.</p>',39),i=[a];function r(n,s,l,g,b,h){return d(),e("div",null,i)}const k=t(c,[["render",r]]);export{u as __pageData,k as default};
